#include <stddef.h>

int check_study_order(const int *prereq, const int *order, int n)
{
    int learned[10];
    int i, k, layer, need;

    if (prereq == NULL || order == NULL || n <= 0 || n > 9) {
        return -1;
    }

    /* 前置表合法性：0 表示无前置，否则必须落在 1..n 且不能自依赖 */
    for (i = 0; i < n; ++i) {
        if (prereq[i] < 0 || prereq[i] > n || prereq[i] == i + 1) {
            return -1;
        }
    }

    /* order 必须是 1..n 的一个排列 */
    for (i = 0; i <= n; ++i) {
        learned[i] = 0;
    }
    for (k = 0; k < n; ++k) {
        if (order[k] < 1 || order[k] > n || learned[order[k]] != 0) {
            return -1;
        }
        learned[order[k]] = 1;
    }

    /* 按计划逐项检查：学第 order[k] 层时，其前置层必须已经学完 */
    for (i = 0; i <= n; ++i) {
        learned[i] = 0;
    }
    for (k = 0; k < n; ++k) {
        layer = order[k];
        need = prereq[layer - 1];

        if (need != 0 && learned[need] == 0) {
            return 0;
        }
        learned[layer] = 1;
    }

    return 1;
}
